START = time.monotonic()


def require(ok, message):
    if not ok: raise ValueError(message)


def tick(event, **values):
    print(json.dumps({'utc':datetime.now(timezone.utc).isoformat(),
                     'elapsed_seconds':round(time.monotonic()-START,3),
                     'event':event, **values}), flush=True)


def safe(p):
    p=Path(p)
    require(not p.is_symlink() and not any(q.is_symlink() for q in p.parents), 'Unsafe symlink: '+str(p))
    return p


def digest(data): return hashlib.sha256(data).hexdigest()

def sha(p):
    p=safe(p);h=hashlib.sha256()
    with p.open('rb') as stream:
        for b in iter(lambda:stream.read(1<<20),b''): h.update(b)
    return h.hexdigest()


def read(p): return json.loads(safe(p).read_text())

def atomic(p, data):
    p=safe(p);safe(p.parent).mkdir(parents=True,exist_ok=True)
    temp=p.parent/('.'+p.name+'.'+uuid.uuid4().hex+'.partial')
    try:
        with temp.open('xb') as f: f.write(data);f.flush();os.fsync(f.fileno())
        os.replace(temp,p)
    finally:
        if temp.exists():temp.unlink()


def atomic_json(p, value): atomic(p,(json.dumps(value,sort_keys=True,indent=2)+'\n').encode())


def copy_verified(src, dst):
    h=sha(src);safe(dst)
    if dst.exists(): require(sha(dst)==h, 'Conflicting destination: '+str(dst))
    else: atomic(dst,safe(src).read_bytes())
    require(sha(dst)==h,'Copy verification failed')


def files_hashes(root):
    return {str(p.relative_to(root)):sha(p) for p in sorted(root.rglob('*')) if p.is_file()}


def fingerprint(identity): return digest(json.dumps(identity,sort_keys=True).encode())


def codes(n): return [''.join(c['source']) for c in n['cells'] if c['cell_type']=='code']


def notebook_update(current):
    require(codes(current) in (codes(ORIGINAL_NOTEBOOK),codes(NEW_NOTEBOOK)),
            'Notebook code was edited; preserve it rather than overwriting')
    result=copy.deepcopy(current)
    oldcode=codes(ORIGINAL_NOTEBOOK);newcode=codes(NEW_NOTEBOOK);index=0
    for c in result['cells']:
        if c['cell_type']=='code':
            c['source']=newcode[index].splitlines(keepends=True)
            c['outputs']=[];c['execution_count']=None;index+=1
    message='\n\n**Numerical continuation update:** The original gradient threshold and statistical model remain unchanged. Near-solutions that stop by objective reduction can receive bounded Newton refinement. Valid earlier checkpoints are retained; see RESUME_GUIDE.md.\n'
    if 'Numerical continuation update' not in ''.join(result['cells'][0]['source']):
        result['cells'][0]['source'].append(message)
    return result


def collect(folder, names):
    safe(folder);c=read(folder/'complete.json')
    require(c.get('complete') is True and set(c.get('outputs',{}))==set(names),'Checkpoint scope mismatch: '+str(folder))
    for name,h in c['outputs'].items():require(sha(folder/name)==h,'Corrupt checkpoint: '+str(folder/name))
    return [folder/n for n in names+['complete.json']]


CHECKPOINT_SCHEMA_ID = 'bt-csv-semantic-20260912'


def compare_checkpoint_table(saved, rebuilt, expected_columns, table_name):
    """Verify CSV semantic identity, not parser-inferred integer/float storage.

    A saved integral feature (for example diff_seed) may be inferred as int64
    although its reproducible builder uses float64 because the source seed
    column also contains unseeded teams. Normalize only declared numeric fields
    IN MEMORY. Never coerce strings/bools, alter saved bytes, sort/reorder rows,
    drop columns, round values, or relax the original 1e-12 value tolerances.
    """
    import numpy as np
    import pandas as pd
    from pandas.api.types import is_numeric_dtype, is_bool_dtype, is_complex_dtype
    keys = ['Gender', 'Season', 'Team1ID', 'Team2ID']
    expected_columns = list(expected_columns)
    require(expected_columns[:4] == keys and len(set(expected_columns)) == len(expected_columns),
            'Invalid declared checkpoint schema: ' + table_name)
    require(list(saved.columns) == expected_columns and list(rebuilt.columns) == expected_columns,
            'Checkpoint column/order mismatch: ' + table_name)
    require(len(saved) == len(rebuilt) and len(saved) > 0 and saved.index.equals(rebuilt.index),
            'Checkpoint row/index mismatch: ' + table_name)
    for label, frame in [('saved', saved), ('rebuilt', rebuilt)]:
        require(not frame.isna().any().any(), 'Checkpoint missing values: ' + table_name + '/' + label)
        require(not frame.duplicated(keys).any(), 'Duplicate checkpoint keys: ' + table_name)
        require(frame.Gender.map(lambda x: isinstance(x, str)).all() and frame.Gender.eq('M').all(),
                'Invalid checkpoint Gender: ' + table_name)
    require(saved.Gender.tolist() == rebuilt.Gender.tolist(), 'Checkpoint Gender differs: ' + table_name)
    normalized = []
    max_error = 0.0
    for column in expected_columns[1:]:
        values = []
        for label, frame in [('saved', saved), ('rebuilt', rebuilt)]:
            series = frame[column]
            require(is_numeric_dtype(series.dtype) and not is_bool_dtype(series.dtype)
                    and not is_complex_dtype(series.dtype),
                    'Nonnumeric/boolean/complex checkpoint column: ' + table_name + '/' + column)
            require(series.abs().le(2**53).all(),
                    'Unsafe numeric conversion in checkpoint: ' + table_name + '/' + column)
            array = series.to_numpy(dtype=np.float64)
            require(np.isfinite(array).all(), 'Nonfinite checkpoint value: ' + table_name + '/' + column)
            if column in keys[1:] or column == 'diff_seed':
                require(np.equal(array, np.floor(array)).all(),
                        'Nonintegral discrete checkpoint value: ' + table_name + '/' + column)
            values.append(array)
        left, right = values
        if column in keys[1:] or column == 'diff_seed':
            require(np.array_equal(left, right), 'Discrete checkpoint values differ: ' + table_name + '/' + column)
        else:
            np.testing.assert_allclose(left, right, rtol=1e-12, atol=1e-12, equal_nan=False,
                                       err_msg='Checkpoint values differ: ' + table_name + '/' + column)
        max_error = max(max_error, float(np.max(np.abs(left-right))))
        if saved[column].dtype != rebuilt[column].dtype:
            normalized.append({'column': column, 'saved_dtype': str(saved[column].dtype),
                               'rebuilt_dtype': str(rebuilt[column].dtype)})
    return {'table': table_name, 'schema_id': CHECKPOINT_SCHEMA_ID,
            'rows_checked': len(saved), 'numeric_columns_checked': len(expected_columns)-1,
            'dtype_normalizations': normalized, 'max_absolute_value_error': max_error,
            'discrete_values_checked_exactly': True, 'value_rtol': 1e-12, 'value_atol': 1e-12,
            'saved_bytes_modified': False}


def numerical_certificates(kit, old, seasons, constraints):
    """Recompute certificates and pair features, never optimize or refit a model."""
    sys.path.insert(0,str(kit));import strength_io as io
    require(io.environment()==constraints['environment'],'Environment differs; do not reinstall')
    repo=Path(os.environ.get('MARCH_REPO',str(Path.home()/'march-machine-learning-mania-2026')))
    require(io.rf.repository_state(repo)==constraints['state'],'Repository differs; do not reset')
    raw=repo/'data/kaggle/raw'
    for n,h in constraints['data'].items():require(sha(io.safe_file(raw,n))==h,'Raw input changed: '+n)
    identity=read(old/'manifest.json');roots={}
    defaults={'shooting':'march_shooting_research','schedule':'march_schedule_research',
              'temporal':'march_temporal_form','possession':'march_possession_research'}
    for k,fp in constraints['fingerprints'].items():
        roots[k]=safe(Path(os.environ.get('MARCH_'+k.upper()+'_KIT',str(Path.home()/defaults[k])))/'private_runs'/fp)
    for k,h in identity['upstream_files'].items():
        origin,rel=k.split('/',1)
        require(k in constraints['upstream_pins'] and constraints['upstream_pins'][k]==h,
                'Unpinned upstream identity: '+k)
        require(sha(io.safe_file(roots[origin],rel))==h,'Upstream changed: '+k)
    namespace={'__name__':'_bounded_bt_verified_source'}
    exec(compile(base64.b64decode(PAYLOAD['win_strength_features.py']),'<verified BT continuation>','exec'),namespace)
    import numpy as np
    import pandas as pd
    from threadpoolctl import threadpool_limits
    # Exercise precisely the function-tolerance/gradient mismatch on tiny
    # analytic arrays; no project observations or fitting function is used.
    from scipy import sparse
    from scipy.optimize import OptimizeResult
    sx=sparse.csr_matrix([[1.,0.],[-1.,0.],[0.,1.],[0.,-1.]])
    sp=np.array([.25,1.]);st=np.array([0.00011029472612167357/.75,0.])
    fake=OptimizeResult(x=st,success=True,message='CONVERGENCE: RELATIVE REDUCTION OF F <= FACTR*EPSMCH',nit=1)
    _,_,sg,si=namespace['certify_solution'](fake,sx,sp)
    require(si['initial_gradient_max_abs']>1e-4 and sg<1e-8 and si['newton_steps']<=8,
            'Numerical continuation smoke test failed')
    tick('numerical_smoke_pass',initial_gradient=si['initial_gradient_max_abs'],
         final_gradient=sg,newton_steps=si['newton_steps'],project_models_fitted=0)
    frame=pd.read_csv(raw/'MRegularSeasonCompactResults.csv',usecols=namespace['INPUTS'])
    certified=[]
    with threadpool_limits(limits=2):
        for season in seasons:
            folder=old/f'ratings/M_{season}'
            model=read(folder/'rating_model.json');diag=read(folder/'diagnostics.json')
            table=io.read_csv(folder/'team_ratings.csv')
            require(model['parameters']==namespace['PARAMETERS'],'Rating parameter identity changed')
            games=namespace['legal_results'](frame,season)
            teams,a,b,x,precision=namespace['design'](games)
            require(model['team_ids']==teams.tolist() and model['Season']==season and model['Gender']=='M',
                    'Rating identities differ')
            theta=np.asarray(model['theta'],dtype=float);cov=np.asarray(model['covariance'],dtype=float)
            require(theta.shape==(len(teams)+1,) and cov.shape==(len(teams)+1,len(teams)+1), 'Rating dimensions differ')
            val,grad=namespace['objective'](theta,x,precision)
            norm=float(np.max(np.abs(grad)));H=namespace['hessian'](theta,x,precision)
            inverse=float(np.max(np.abs(H@cov-np.eye(len(H)))))
            require(np.isfinite(theta).all() and np.isfinite(cov).all() and np.isfinite(val) and
                    np.isfinite(norm) and norm<=namespace['PARAMETERS']['gradient_acceptance'] and
                    inverse<1e-7 and np.max(abs(cov-cov.T))<1e-10 and (np.diag(cov)>0).all(),
                    'Saved rating fails the unchanged numerical certificate')
            require(model['diagnostics']==diag and abs(diag['gradient_max_abs']-norm)<1e-8 and
                    abs(diag['negative_log_posterior']-val)<1e-8 and diag['regular_games']==len(games),
                    'Recorded rating diagnostic differs')
            require(table.TeamID.tolist()==teams.tolist() and np.max(abs(table.bt_ability-theta[:-1]))<1e-12 and
                    np.max(abs(table.bt_marginal_sd-np.sqrt(np.diag(cov)[:-1])))<1e-12,'Rating table differs')
            base=io.read_csv(roots['shooting']/f'snapshots/M_{season}/teams.csv')
            pairs,pair_diag,support=namespace['build_matchups'](base,model,table)
            schemas = {
                'matchups.csv': namespace['KEYS'] + namespace['ALL'],
                'pair_diagnostics.csv': namespace['KEYS'] + ['bt_logodds_difference', 'pair_variance',
                    'bt_point_probability', 'bt_averaged_probability', 'quadrature_error_bound_check']}
            table_certificates = []
            for name,new in [('matchups.csv',pairs),('pair_diagnostics.csv',pair_diag)]:
                saved=io.read_csv(old/f'snapshots/M_{season}'/name)
                table_certificates.append(compare_checkpoint_table(saved, new, schemas[name], name))
            require(read(old/f'snapshots/M_{season}/support.json')==support,'Pair support differs')
            certified.append({'Season':season,'gradient_max_abs':norm,'covariance_inverse_error':inverse,
                              'refitted':False,'pair_features_verified':True,
                              'table_certificates':table_certificates})
            tick('checkpoint_certified',season=season,gradient_max_abs=norm)
    return certified


def plan_migration(kit, verifier=numerical_certificates):
    pointer=read(kit/'reports/latest_run.json');old=safe(Path(pointer['run_dir']))
    require(old.is_dir() and old.resolve().parent==safe(kit/'private_runs').resolve(), 'Run is outside the kit')
    fp=old.name;manifest=read(old/'manifest.json');identity={k:v for k,v in manifest.items() if k!='fingerprint'}
    require(re.fullmatch('[0-9a-f]{64}',fp) and pointer['fingerprint']==fp and manifest['fingerprint']==fp and fingerprint(identity)==fp,'Invalid old run fingerprint')
    require(set(identity['source'])==set(SOURCES),'Unexpected source scope')
    for n,h in identity['source'].items():
        if n in PAYLOAD:require(h in [OLD_HASHES[n],NEW_HASHES[n]],'Unknown source identity')
        else:require(h==sha(kit/n),'Unchanged source differs: '+n)
    if all(identity['source'][n]==NEW_HASHES[n] for n in PAYLOAD):
        migration=read(old/'cache_migration.json')
        for rel,h in migration['copied_sha256'].items():require(sha(safe(old/rel))==h,'Migrated checkpoint changed')
        return {'already':True,'old':old,'new':old,'receipt':migration}
    require(all(identity['source'][n]==OLD_HASHES[n] for n in PAYLOAD),'Mixed run identity')
    c=read(kit/'constraints.json')
    require(sha(kit/'constraints.json')==identity['constraints_sha256'],'Constraints changed')
    for n,key in [('data','data'),('environment','environment'),('upstream_fingerprints','fingerprints'),('reference_commit','reference_commit')]:
        require(identity[n]==c[key],'Old run/constraint mismatch: '+n)
    for n,h in identity['evidence_sha256'].items():
        require(not Path(n).is_absolute() and '..' not in Path(n).parts,'Unsafe evidence')
        require(sha(kit/n)==h,'Evidence changed: '+n)
    seasons=[];files=[]
    if (old/'fits').exists():require(not any((old/'fits').rglob('*')),'Unexpected downstream fits; do not migrate across a scientific change')
    for s in range(2013,2020):
        rating=old/f'ratings/M_{s}';pair=old/f'snapshots/M_{s}'
        if (rating/'complete.json').exists():
            files+=collect(rating,RATING_FILES);files+=collect(pair,PAIR_FILES);seasons.append(s)
        else:require(not (pair/'complete.json').exists(),'Pair without completed rating')
    require(seasons[:2]==[2013,2014] and seasons==list(range(2013,2013+len(seasons))),
            'Expected the completed 2013 and 2014 checkpoint pairs; stop rather than silently refit')
    certificates=verifier(kit,old,seasons,c)
    before=files_hashes(old)
    ni=copy.deepcopy(identity)
    for n,h in NEW_HASHES.items():ni['source'][n]=h
    nfp=fingerprint(ni);new=safe(kit/'private_runs'/nfp);nm=dict(ni,fingerprint=nfp)
    if new.exists() and (new/'manifest.json').exists():require(read(new/'manifest.json')==nm,'Destination manifest differs')
    for f in files:
        d=new/f.relative_to(old)
        if d.exists():require(sha(d)==sha(f),'Destination checkpoint conflict')
    size=sum(f.stat().st_size for f in files)
    require(size<128*1024**2 and shutil.disk_usage(kit).free>2*size+16*1024**2,'Insufficient disk or migration exceeds cap')
    return dict(already=False,old=old,new=new,manifest=nm,files=files,before=before,seasons=seasons,certificates=certificates)


def apply(kit, verifier=numerical_certificates):
    kit=safe(Path(kit).expanduser()).resolve();require(kit.is_dir(),'Missing kit')
    reports=safe(kit/'reports');require(reports.is_dir(),'Missing existing reports; do not restart setup')
    # Never load user-modified numerical source or silently weaken recorded pins.
    for n,h in PINNED.items():require(sha(kit/n)==h,'Delivered unchanged file differs: '+n)
    for n,h in OLD_HASHES.items():require(sha(kit/n) in [h,NEW_HASHES[n]],'Unexpected source edit: '+n)
    manifest=read(kit/'MANIFEST.json')
    require('sha256' in manifest,'Invalid package manifest')
    current=read(kit/NOTEBOOK);corrected=notebook_update(current)
    with safe(reports/'execution.lock').open('a') as lock:
        try:fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        except BlockingIOError:raise ValueError('Another stage is running; shut down its kernel first')
        tick('verify_and_plan',hard_limit_seconds=180)
        plan=plan_migration(kit,verifier)
        if plan['already']:
            require(all(sha(kit/n)==h for n,h in NEW_HASHES.items()),'Updated run but source rollback detected')
            result=dict(status='PASS_ALREADY_UPDATED',ratings_reused=len(plan['receipt']['seasons']),
                        models_fitted=0,new_run=str(plan['new']))
            tick('complete',**result);return result
        backup=reports/'numerical_update_backups'/(datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')+'-'+uuid.uuid4().hex[:8])
        old_files=list(PAYLOAD)+[NOTEBOOK,'MANIFEST.json']
        originals={n:safe(kit/n).read_bytes() for n in old_files}
        for n in old_files:copy_verified(kit/n,backup/n)
        for n in ['failure.json','win_strength_prepare.log','latest_run.json']:
            if (reports/n).is_file():copy_verified(reports/n,backup/'reports'/n)
        atomic_json(backup/'backup_manifest.json',{'sha256':{n:digest(b) for n,b in originals.items()},'old_run':str(plan['old'])})
        tick('backup_complete',directory=str(backup))
        new=plan['new'];safe(new).mkdir(parents=True,exist_ok=True)
        # Copy completed bytes before changing source; leave the source run intact.
        atomic_json(new/'manifest.json',plan['manifest'])
        for p in plan['files']:copy_verified(p,new/p.relative_to(plan['old']))
        migration={'status':'VERIFIED_NUMERICAL_CONTINUATION_REUSE','old_run_fingerprint':plan['old'].name,
                   'new_run_fingerprint':new.name,'seasons':plan['seasons'],
                   'copied_sha256':{str(p.relative_to(plan['old'])):sha(p) for p in plan['files']},
                   'certificates':plan['certificates'],'prior_gradient_acceptance':1e-4,'new_gradient_acceptance':1e-4,
                   'objective_changed':False,'priors_changed':False,'feature_definitions_changed':False,
                   'tournament_recipe_changed':False,'rating_solver_path_changed':True,'models_fitted':0,
                   'source_before':OLD_HASHES,'source_after':NEW_HASHES}
        atomic_json(new/'cache_migration.json',migration)
        require(files_hashes(plan['old'])==plan['before'],'Original run changed during migration')
        modified=[]
        try:
            for n,encoded in PAYLOAD.items():atomic(kit/n,base64.b64decode(encoded));modified.append(n)
            atomic_json(kit/NOTEBOOK,corrected);modified.append(NOTEBOOK)
            updated=copy.deepcopy(manifest)
            for n in list(PAYLOAD)+[NOTEBOOK]:updated['sha256'][n]=sha(kit/n)
            atomic_json(kit/'MANIFEST.json',updated);modified.append('MANIFEST.json')
            require(all(sha(kit/n)==h for n,h in NEW_HASHES.items()),'Post-update source verification failed')
            result={'status':'PASS_NUMERICAL_CONTINUATION_UPDATE','ratings_reused':len(plan['seasons']),
                    'matchup_tables_reused':len(plan['seasons']),'models_fitted':0,'old_run_unchanged':True,
                    'gradient_acceptance_unchanged':True,'environment_modified':False,'repository_modified':False,
                    'new_run':str(new),'old_run':str(plan['old']),'backup':str(backup),
                    'remaining_rating_seasons':[s for s in range(2013,2020) if s not in plan['seasons']]}
            atomic_json(reports/'numerical_update.json',result)
            atomic_json(reports/'latest_run.json',{'run_dir':str(new),'fingerprint':new.name})
        except BaseException:
            for n in reversed(modified):atomic(kit/n,originals[n])
            raise
        tick('complete',**result);return result


