# Do not overwrite user-authored cells. Accept only the three delivered versions.
def notebook_update(current):
    require(codes(current) in (codes(ORIGINAL_NOTEBOOK), codes(NEW_NOTEBOOK),
                              codes(GUARDED_NOTEBOOK)),
            'Notebook code was edited; preserve it rather than overwriting')
    result = copy.deepcopy(current)
    target = codes(GUARDED_NOTEBOOK)
    i = 0
    for cell in result['cells']:
        if cell['cell_type'] == 'code':
            cell['source'] = target[i].splitlines(keepends=True)
            cell['outputs'] = []; cell['execution_count'] = None; i += 1
    if 'Verified installation' not in ''.join(result['cells'][0]['source']):
        result['cells'][0]['source'].append(GUARDED_NOTEBOOK['cells'][0]['source'][-1])
    return result

# This executes in a NEW interpreter importing the actual installed module, not
# the updater's in-memory payload. It does not call minimize or fit_season.
